-- Biblioteca maestra inicial de partidas extraída de las facturas 2025-2026.
-- Solo importa estructura técnica; los precios históricos se excluyen deliberadamente.

alter table public.sistemas_rendimiento
  add column if not exists capitulo text,
  add column if not exists categoria_detalle text,
  add column if not exists grupo text,
  add column if not exists origen text not null default 'manual';

create index if not exists sistemas_rendimiento_capitulo_idx
  on public.sistemas_rendimiento (capitulo, categoria_detalle, codigo);

comment on column public.sistemas_rendimiento.capitulo is
  'Capítulo principal de la biblioteca de partidas.';
comment on column public.sistemas_rendimiento.categoria_detalle is
  'Categoría técnica dentro del capítulo.';
comment on column public.sistemas_rendimiento.grupo is
  'Agrupación funcional de partidas equivalentes.';
comment on column public.sistemas_rendimiento.origen is
  'Procedencia de la ficha: manual, biblioteca histórica u otra importación controlada.';

insert into public.sistemas_rendimiento (
  codigo,
  nombre,
  categoria,
  unidad_base,
  descripcion,
  capitulo,
  categoria_detalle,
  grupo,
  origen,
  estado,
  version,
  activo
)
values
  ('1.1.01', 'Cuadro CGBT de comunidad completo', 'electricidad', 'ud', 'Suministro e instalación de cuadro general de baja tensión para servicios comunes de la finca, en ejecución trifásica para ascensores y monofásica para alumbrado y enchufes de comunidad, con interruptor general, diferenciales (selectivo superinmunizado en la línea de ascensores), magnetotérmicos por circuito y toma de corriente en carril, incluso traslado de líneas existentes, conexionado, pruebas y puesta en servicio.', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Cuadros generales de baja tensión (CGBT) de comunidad', 'biblioteca_facturas_2025_2026'),
  ('1.1.02', 'Unificación de cuadros CGBT', 'electricidad', 'ud', 'Unificación de dos o más cuadros generales de servicios comunes en un único cuadro de mayor capacidad, con traslado y recableado de todos los circuitos, nueva aparamenta donde sea necesario, canalización entre cuadros, identificación de circuitos y puesta en servicio.', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Cuadros generales de baja tensión (CGBT) de comunidad', 'biblioteca_facturas_2025_2026'),
  ('1.1.03', 'Ampliación o aparamenta adicional en cuadro existente', 'electricidad', 'ud', 'Suministro e instalación de aparamenta en cuadro existente (diferencial, magnetotérmico, contactor, conmutador o reloj de carril DIN) para completar protecciones exigidas por normativa o independizar una línea (ascensores, bombas, alumbrado), con recableado de puentes, conexionado y pruebas de funcionamiento.', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Cuadros generales de baja tensión (CGBT) de comunidad', 'biblioteca_facturas_2025_2026'),
  ('1.1.04', 'Identificación de circuitos, marcado y recableado de cuadros', 'electricidad', 'ud', 'Revisión de cuadros de servicios comunes con identificación de todos los circuitos, marcado de conductores, recableado y reapriete de conexiones, saneado de empalmes y reordenación del cableado, dejando el cuadro conforme a normativa y preparado para inspección.', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Cuadros generales de baja tensión (CGBT) de comunidad', 'biblioteca_facturas_2025_2026'),
  ('1.1.05', 'Protección contra contactos directos y tapas', 'electricidad', 'ud', 'Corrección de defectos de protección contra contactos directos en cuadros y cajas: suministro y montaje de tapas obturadoras, tapas de bornero, tapas de cajas de registro o pantallas de metacrilato, dejando todas las partes activas inaccesibles.', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Cuadros generales de baja tensión (CGBT) de comunidad', 'biblioteca_facturas_2025_2026'),
  ('1.1.06', 'Cerradura o candado de compañía en CGP', 'electricidad', 'ud', 'Suministro e instalación de cerradura normalizada con llave de compañía distribuidora (o candado de compañía) en puerta de hornacina de caja general de protección, con retirada de la existente averiada y, en su caso, adaptación de chapa o escudo.', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Caja general de protección (CGP)', 'biblioteca_facturas_2025_2026'),
  ('1.1.07', 'Sustitución de fusibles en CGP', 'electricidad', 'ud', 'Sustitución de fusibles de cuchilla NH en caja general de protección, adecuando el calibre a la línea general de alimentación según normativa (p. ej. 250 A → 160 A), con corte de suministro coordinado, maniobra en condiciones de seguridad y comprobación final.', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Caja general de protección (CGP)', 'biblioteca_facturas_2025_2026'),
  ('1.1.08', 'Anclaje, reparación y adecuación de CGP', 'electricidad', 'ud', 'Trabajos de adecuación de caja general de protección y su hornacina: anclaje de la caja con pletina, retirada de bridas, soldadura de pernos y pintado de puerta, reparación de cierres o sustitución de la CGP por otra de esquema normalizado con interruptor de corte.', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Caja general de protección (CGP)', 'biblioteca_facturas_2025_2026'),
  ('1.1.09', 'Derivación individual', 'electricidad', 'ud', 'Suministro e instalación de derivación individual en conductor de cobre libre de halógenos de sección según potencia (3x10, 3x16 o 5x16 mm²) bajo tubo, desde la centralización de contadores hasta el cuadro de la vivienda o local, incluso conexionado y pruebas.', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Centralización de contadores, LGA y derivaciones individuales', 'biblioteca_facturas_2025_2026'),
  ('1.1.10', 'Línea general de alimentación (LGA)', 'electricidad', 'ud', 'Suministro e instalación de línea general de alimentación con conductores unipolares RZ1 libres de halógenos de sección según cálculo, bajo tubo, desde la CGP hasta la centralización de contadores, incluso conexionado en ambos extremos.', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Centralización de contadores, LGA y derivaciones individuales', 'biblioteca_facturas_2025_2026'),
  ('1.1.11', 'Centralización de contadores y bases portafusibles', 'electricidad', 'ud', 'Suministro e instalación o adecuación de centralización de contadores (columna modular, armario con puertas E30, bases portafusibles monofásicas o trifásicas) incluso revisión del conexionado, corte de suministro y puesta en servicio.', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Centralización de contadores, LGA y derivaciones individuales', 'biblioteca_facturas_2025_2026'),
  ('1.1.12', 'Traslado de contador al exterior', 'electricidad', 'ud', 'Traslado de contador eléctrico desde el interior de la vivienda a fachada o zona común, con nuevo módulo de contador homologado y nueva derivación individual hasta el cuadro de la vivienda.', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Centralización de contadores, LGA y derivaciones individuales', 'biblioteca_facturas_2025_2026'),
  ('1.1.13', 'Puesta a tierra de finca y cuadros', 'electricidad', 'ud', 'Ejecución o reparación de red de puesta a tierra: pletina de cobre con bornas en cuarto de contadores, caja de comprobación de tierras, pica y cable desnudo de cobre, o línea de tierra desde cuadros de ascensores y cajas metálicas hasta el borne principal, con medición final.', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Puesta a tierra', 'biblioteca_facturas_2025_2026'),
  ('1.1.14', 'Cuadro de superficie con cerradura sobre existente', 'electricidad', 'ud', 'Suministro e instalación de cuadro eléctrico de superficie con puerta y cerradura colocado sobre el cuadro existente, con traslado de la aparamenta, recableado e identificación de circuitos.', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Cuadros de vivienda y locales', 'biblioteca_facturas_2025_2026'),
  ('1.1.15', 'Cuadro general de mando y protección de vivienda', 'electricidad', 'ud', 'Suministro e instalación de cuadro general de mando y protección de vivienda de empotrar de 24 a 36 elementos, con interruptor general 32 A, dos diferenciales 2x40 A 30 mA y magnetotérmicos por circuito (alumbrado, enchufes, cocina/horno, lavadora, baños, climatización), conexionado, identificación de circuitos y pruebas.', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Cuadros de vivienda y locales', 'biblioteca_facturas_2025_2026'),
  ('1.1.16', 'Cofret o cuadro industrial estanco', 'electricidad', 'ud', 'Sustitución de cuadro estanco IP67 con bases industriales IP44 y automático tetrapolar para tomas de fuerza en exteriores o zonas técnicas.', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Cuadros de vivienda y locales', 'biblioteca_facturas_2025_2026'),
  ('1.1.17', 'Tubo PVC para manguera CGBT a caja registro (~3 ml)', 'electricidad', 'ud', 'Tubo PVC para manguera CGBT a caja registro (~3 ml).', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Trabajos singulares', 'biblioteca_facturas_2025_2026'),
  ('1.1.18', 'Desconexión y anulación de ICP', 'electricidad', 'ud', 'Desconexión y anulación de ICP.', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Trabajos singulares', 'biblioteca_facturas_2025_2026'),
  ('1.1.19', 'Desconexión y retirada línea grupo de presión', 'electricidad', 'ud', 'Desconexión y retirada línea grupo de presión.', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Trabajos singulares', 'biblioteca_facturas_2025_2026'),
  ('1.1.20', 'Sustitución enchufe doble con toma de tierra', 'electricidad', 'ud', 'Sustitución enchufe doble con toma de tierra.', '1. Electricidad', '1.1 Cuadros, CGP, centralización y puesta a tierra', 'Trabajos singulares', 'biblioteca_facturas_2025_2026'),
  ('1.2.01', 'Esquema unifilar de cuadro con levantamiento', 'electricidad', 'ud (por cuadro)', 'Levantamiento de la instalación existente y elaboración de esquema unifilar del cuadro general de servicios comunes, firmado por instalador autorizado, impreso y colocado en el propio cuadro para cumplimiento de inspección OCA.', '1. Electricidad', '1.2 Documentación, legalizaciones y revisiones', 'Esquemas y rotulación', 'biblioteca_facturas_2025_2026'),
  ('1.2.02', 'Rotulación e identificación de cuadro', 'electricidad', 'ud', 'Rotulación de cuadro eléctrico con identificación de cada circuito mediante etiquetas y señalización de riesgo eléctrico.', '1. Electricidad', '1.2 Documentación, legalizaciones y revisiones', 'Esquemas y rotulación', 'biblioteca_facturas_2025_2026'),
  ('1.2.03', 'Levantamiento técnico con planos de estado actual', 'electricidad', 'ud', 'Levantamiento técnico de la instalación eléctrica existente con elaboración de planos de estado actual, para subsanación de defectos de inspección OCA.', '1. Electricidad', '1.2 Documentación, legalizaciones y revisiones', 'Esquemas y rotulación', 'biblioteca_facturas_2025_2026'),
  ('1.2.04', 'Boletín eléctrico (CIE) presentado en Industria', 'electricidad', 'ud', 'Emisión de certificado de instalación eléctrica (boletín) por instalador autorizado, con revisión de la instalación, documentación y presentación telemática en la Dirección General de Industria; tasas aparte salvo indicación.', '1. Electricidad', '1.2 Documentación, legalizaciones y revisiones', 'Boletines y legalizaciones', 'biblioteca_facturas_2025_2026'),
  ('1.2.05', 'Legalización de instalación de finca (modificación >25 %)', 'electricidad', 'ud', 'Legalización de la instalación de servicios comunes por modificación superior al 25 %, con memoria técnica, boletín eléctrico y tramitación ante Industria.', '1. Electricidad', '1.2 Documentación, legalizaciones y revisiones', 'Boletines y legalizaciones', 'biblioteca_facturas_2025_2026'),
  ('1.2.06', 'Inspección eléctrica con informe de deficiencias', 'electricidad', 'ud', 'Visita de inspección de la instalación eléctrica con revisión de cuadros, tierras y circuitos, emisión de informe de deficiencias y, en su caso, presupuesto de subsanación.', '1. Electricidad', '1.2 Documentación, legalizaciones y revisiones', 'Revisiones e inspecciones', 'biblioteca_facturas_2025_2026'),
  ('1.2.07', 'Proyecto de actividad e instalaciones para licencia de cafetería en…', 'electricidad', 'ud', 'Proyecto de actividad e instalaciones para licencia de cafetería en Av. Doctor Manuel Jarabo 59, San Martín de la Vega, con delineación, proyecto BT para OCA, visado COITIM, dirección y certificado final de obra, tasas OCA incluidas.', '1. Electricidad', '1.2 Documentación, legalizaciones y revisiones', 'Trabajos singulares', 'biblioteca_facturas_2025_2026'),
  ('1.2.08', 'Garaje (acta OCA 197089): estudio de clasificación de áreas Clase…', 'electricidad', 'ud', 'Garaje (acta OCA 197089): estudio de clasificación de áreas Clase 1/Clase 2 por riesgo de incendio y explosión, con informe técnico justificativo.', '1. Electricidad', '1.2 Documentación, legalizaciones y revisiones', 'Trabajos singulares', 'biblioteca_facturas_2025_2026'),
  ('1.3.01', 'Plafón LED 18 W slim de superficie con detector', 'electricidad', 'ud', 'Suministro e instalación de plafón LED circular slim de superficie de 18 W, 4500 K, con detector de movimiento y sensor lumínico integrados, en rellanos y escalera de zonas comunes, con retirada y gestión de las luminarias antiguas y conexionado.', '1. Electricidad', '1.3 Alumbrado de zonas comunes', 'Renovación de alumbrado de escalera con detectores', 'biblioteca_facturas_2025_2026'),
  ('1.3.02', 'Plafón LED 18 W slim de empotrar con detector (portal)', 'electricidad', 'ud', 'Suministro e instalación de plafón LED slim de empotrar de 18 W con detector de movimiento y sensor lumínico en falso techo de portal, con ajuste de hueco y retirada de luminaria existente.', '1. Electricidad', '1.3 Alumbrado de zonas comunes', 'Renovación de alumbrado de escalera con detectores', 'biblioteca_facturas_2025_2026'),
  ('1.3.03', 'Reconexión de interruptores/pulsadores con tapa ciega', 'electricidad', 'ud', 'Desmontaje de pulsador o interruptor de alumbrado de escalera, reconexión del circuito para funcionamiento con detectores de presencia y colocación de tapa ciega en la caja.', '1. Electricidad', '1.3 Alumbrado de zonas comunes', 'Renovación de alumbrado de escalera con detectores', 'biblioteca_facturas_2025_2026'),
  ('1.3.04', 'Plafón LED de superficie con detector (otros modelos)', 'electricidad', 'ud', 'Suministro e instalación de plafón LED de superficie con detector de presencia y sensor lumínico (modelos con bombillas E27 o LED integrado, modo día/noche), con retirada de la luminaria existente.', '1. Electricidad', '1.3 Alumbrado de zonas comunes', 'Renovación de alumbrado de escalera con detectores', 'biblioteca_facturas_2025_2026'),
  ('1.3.05', 'Downlight LED 20 W con detector en zonas comunes', 'electricidad', 'ud', 'Suministro e instalación de downlight LED de 20 a 25 W (empotrar o superficie, redondo o cuadrado, 4500–6500 K), con detector de presencia y lumínico cuando procede, en portal, buzones o rellanos, con retirada del existente.', '1. Electricidad', '1.3 Alumbrado de zonas comunes', 'Renovación de alumbrado de escalera con detectores', 'biblioteca_facturas_2025_2026'),
  ('1.3.06', 'Detector crepuscular / interruptor crepuscular', 'electricidad', 'ud', 'Suministro e instalación de interruptor crepuscular en azotea o fachada con línea desde el cuadro general bajo canaleta, anulación del reloj existente cuando procede, regulación y puesta en marcha.', '1. Electricidad', '1.3 Alumbrado de zonas comunes', 'Control de encendido de zonas comunes', 'biblioteca_facturas_2025_2026'),
  ('1.3.07', 'Reloj de alumbrado en cuadro', 'electricidad', 'ud', 'Suministro e instalación de reloj horario o astronómico en carril DIN en el cuadro de servicios comunes para el encendido de alumbrado, programación y pruebas.', '1. Electricidad', '1.3 Alumbrado de zonas comunes', 'Control de encendido de zonas comunes', 'biblioteca_facturas_2025_2026'),
  ('1.3.08', 'Punto de luz o plafón exterior en acceso a portal', 'electricidad', 'ud', 'Suministro e instalación de punto de luz exterior en acceso a portal con plafón o foco LED de superficie con detector, canalización con canaleta o tubo, caja de registro y conexionado.', '1. Electricidad', '1.3 Alumbrado de zonas comunes', 'Alumbrado exterior y de accesos', 'biblioteca_facturas_2025_2026'),
  ('1.3.09', 'Aviso: sustitución de detector de presencia', 'electricidad', 'ud', 'Atención de aviso por fallo de encendido en zonas comunes, con diagnóstico y sustitución del detector de presencia averiado por otro con sensor lumínico, regulación y comprobación.', '1. Electricidad', '1.3 Alumbrado de zonas comunes', 'Avisos de alumbrado de zonas comunes', 'biblioteca_facturas_2025_2026'),
  ('1.3.10', 'Aviso: sustitución de reloj minutero de escalera', 'electricidad', 'ud', 'Atención de aviso con sustitución de reloj minutero o pulsador de escalera averiado (Orbis T11/T20 o similar), conexionado, ajuste de temporización y puesta en marcha.', '1. Electricidad', '1.3 Alumbrado de zonas comunes', 'Avisos de alumbrado de zonas comunes', 'biblioteca_facturas_2025_2026'),
  ('1.3.11', 'Aviso: sustitución de luminaria o bombilla', 'electricidad', 'ud', 'Atención de aviso por luminaria averiada en zonas comunes con sustitución de downlight, plafón, foco o bombilla (GU10, E27, dicroica) por otro LED de características similares, con retirada del averiado.', '1. Electricidad', '1.3 Alumbrado de zonas comunes', 'Avisos de alumbrado de zonas comunes', 'biblioteca_facturas_2025_2026'),
  ('1.3.12', 'Sustitución pulsador de encendido', 'electricidad', 'ud', 'Sustitución pulsador de encendido.', '1. Electricidad', '1.3 Alumbrado de zonas comunes', 'Trabajos singulares', 'biblioteca_facturas_2025_2026'),
  ('1.4.01', 'Visita de diagnóstico sin reparación', 'electricidad', 'ud', 'Desplazamiento y visita de técnico para diagnóstico de avería eléctrica, revisión de cuadros y encendidos, sin reparación por no hallarse avería o por ser ajena a la instalación del cliente.', '1. Electricidad', '1.4 Avisos y reparaciones eléctricas', 'Visitas y diagnósticos', 'biblioteca_facturas_2025_2026'),
  ('1.4.02', 'Aviso: reparación de alumbrado comunitario', 'electricidad', 'ud', 'Atención de aviso por avería en alumbrado de zonas comunes, con sustitución de detector, reloj, foco, bombillas o pulsador averiado y puesta en marcha.', '1. Electricidad', '1.4 Avisos y reparaciones eléctricas', 'Reparaciones eléctricas', 'biblioteca_facturas_2025_2026'),
  ('1.4.03', 'Reparación de línea o conexiones', 'electricidad', 'ud', 'Reparación de avería eléctrica en línea o cuadro: reapriete de conexiones, saneado o sustitución de tramo de línea, línea provisional de neutro por cortocircuito o localización de circuitos ocultos.', '1. Electricidad', '1.4 Avisos y reparaciones eléctricas', 'Reparaciones eléctricas', 'biblioteca_facturas_2025_2026'),
  ('1.4.04', 'Sustitución de mecanismo eléctrico', 'electricidad', 'ud', 'Sustitución de mecanismo eléctrico averiado (enchufe, interruptor, pulsador, zumbador) por mecanismo Solera Gama Europa o similar.', '1. Electricidad', '1.4 Avisos y reparaciones eléctricas', 'Reparaciones eléctricas', 'biblioteca_facturas_2025_2026'),
