  ('1.4.06', 'Trabajos según parte #f5526265 (sin detalle)', 'electricidad', 'ud', 'Trabajos según parte #f5526265 (sin detalle).', '1. Electricidad', '1.4 Avisos y reparaciones eléctricas', 'Trabajos singulares', 'biblioteca_facturas_2025_2026'),
  ('1.4.07', 'Suministro e instalación de guardamotor (disyuntor magnético 4-6,3 A…', 'electricidad', 'ud', 'Suministro e instalación de guardamotor (disyuntor magnético 4-6,3 A con contacto auxiliar NA+NC) en depuradora de piscina, con retirada del averiado y puesta en marcha.', '1. Electricidad', '1.4 Avisos y reparaciones eléctricas', 'Trabajos singulares', 'biblioteca_facturas_2025_2026'),
